diff --git a/src/documents.ts b/src/documents.ts
index d771919..11bc2cf 100644
--- a/src/documents.ts
+++ b/src/documents.ts
@@ -13,3 +13,8 @@ export interface Doc {
 export function canEdit(user: User, doc: Doc): boolean {
   return user.admin || doc.ownerId === user.id;
 }
+
+/** The documents a user may see: every public one, and the private ones they can edit. */
+export function visibleDocuments(user: User, docs: Doc[]): Doc[] {
+  return docs.filter((doc) => !doc.private || !canEdit(user, doc));
+}
diff --git a/src/listing.ts b/src/listing.ts
