--- a/src/listing.ts
+++ b/src/listing.ts
@@ -1,5 +1,5 @@
-import type { Doc } from "./documents.ts";
+import { type Doc, type User, visibleDocuments } from "./documents.ts";

-export function listTitles(docs: Doc[]): string[] {
-  return docs.map((doc) => doc.title);
+export function listTitles(user: User, docs: Doc[]): string[] {
+  return visibleDocuments(user, docs).map((doc) => doc.title);
 }
